function selectIssue(event, repository) {
  const issue = event.issue;
  if (event.repository?.full_name?.toLowerCase() !== repository.toLowerCase()
      || event.repository.default_branch !== 'master'
      || event.action !== 'labeled' || event.label?.name !== 'bug'
      || issue?.state !== 'open' || issue.pull_request
      || !['OWNER', 'MEMBER', 'COLLABORATOR'].includes(issue.author_association)
      || !Number.isSafeInteger(issue.number) || issue.number < 1) return null;
  const title = String(issue.title ?? '').trim();
  const body = String(issue.body ?? '').trim();
  if (!title || !body || title.length > 300 || body.length > 6000) return null;
  if (/security|vulnerab|exploit|cve[- ]|credential|injection|уязвим|эксплойт|инъекц/i.test(title + '\n' + body)) return null;
  return { number: issue.number, title, body, branch: 'ai-fix/issue-' + issue.number };
}
