function applyChange(source, proposal) {
  const { oldLine, newLine } = proposal;
  if (typeof oldLine !== 'string' || typeof newLine !== 'string' || oldLine === newLine
      || oldLine.length > 180 || newLine.length > 180 || /[\r\n]/.test(oldLine + newLine)) {
    throw new Error('Ожидалась одна изменённая строка арифметики');
  }
  const declaration = /^(  const (productQuantity|production|total|revenue|profit|cents) = )(.+)$/;
  const original = declaration.exec(oldLine);
  const replacement = declaration.exec(newLine);
  if (!original || !replacement || original[1] !== replacement[1]) {
    throw new Error('Строка выходит за пределы разрешённой арифметики');
  }
  // Only arithmetic over the operands already present on this particular line.
  const call = /BigInt\(order\.(?:jobFeeIsk|saleFeeIsk|saleUnitPriceIsk)\)/g;
  const operand = /^[A-Za-z0-9]/;
  function tokenize(expression) {
    return expression.match(/BigInt\(order\.(?:jobFeeIsk|saleFeeIsk|saleUnitPriceIsk)\)|[A-Za-z][\w]*(?:\.[A-Za-z][\w]*)*|\d+n?|[()+*/% -]/g) ?? [];
  }
  const before = new Set(tokenize(original[3]).filter(token => operand.test(token)));
  const after = tokenize(replacement[3]);
  if (after.join('') !== replacement[3] || /\+\+|--|\/\/|\/\*|\*\//.test(replacement[3])
      || after.some(token => operand.test(token) && !before.has(token))
      || /[A-Za-z0-9_)]\s*\(/.test(replacement[3].replace(call, 'feeOperand'))) {
    throw new Error('Новая формула использует неподдерживаемые операции или операнды');
  }
  const lines = source.split('\n');
  const index = lines.indexOf(oldLine);
  if (index < 0 || index !== lines.lastIndexOf(oldLine)) throw new Error('Исходная строка должна встречаться ровно один раз');
  lines[index] = newLine;
  return lines.join('\n');
}
