function verifyDiff(files, path, proposal) {
  if (!Array.isArray(files) || files.length !== 1) throw new Error('Ожидался один изменённый файл');
  const [file] = files;
  if (file.filename !== path || file.status !== 'modified' || file.additions !== 1 || file.deletions !== 1
      || typeof file.patch !== 'string') throw new Error('Diff вышел за рамки запланированной правки');
  const lines = file.patch.split('\n');
